py_code = '''
import json

def solve(grid):
    if not grid:
        return []
    H, W = len(grid), len(grid[0])

    # Find background color (most frequent)
    count = {}
    for r in range(H):
        for c in range(W):
            count[grid[r][c]] = count.get(grid[r][c], 0) + 1
    bg = max(count, key=count.get)

    # Check full rows and columns of non-background color
    good_rows = set()
    good_cols = set()

    for r in range(H):
        row_vals = [grid[r][c] for c in range(W)]
        non_bg_count = sum(1 for x in row_vals if x != bg)
        if non_bg_count == W and bg != 0:  # Non-background means no 0s
            good_rows.add(r)

    for c in range(W):
        col_vals = [grid[r][c] for r in range(H)]
        non_bg_count = sum(1 for x in col_vals if x != bg)
        if non_bg_count == H and bg != 0:
            good_cols.add(c)

    # Recolor to 2
    result = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if r in good_rows or c in good_cols:
                result[r][c] = 2

    return result
'''
